Automat nhỏ nhất nhận mọi xâu con, O(n) trạng thái (≤ 2n).
```cpp
struct SAM { struct St { int len, link; map<char,int> nx; }; vector<St> st; int last = 0;
  SAM() { st.push_back({0, -1, {}}); }
  void extend(char c) { int cur = st.size(); st.push_back({st[last].len + 1, 0, {}}); int p = last;
    while (p != -1 && !st[p].nx.count(c)) { st[p].nx[c] = cur; p = st[p].link; }
    if (p != -1) { int q = st[p].nx[c];
      if (st[p].len + 1 == st[q].len) st[cur].link = q;
      else { int cl = st.size(); st.push_back({st[p].len + 1, st[q].link, st[q].nx});
        while (p != -1 && st[p].nx[c] == q) { st[p].nx[c] = cl; p = st[p].link; }
        st[q].link = st[cur].link = cl; } }
    last = cur; } };
```
- Số xâu con khác nhau = Σ (len[v] - len[link[v]]). Xâu con chung dài nhất của S, T: dựng SAM của S, chạy T trên automat.

- Segment tree bền vững: mỗi cập nhật tạo O(log n) nút mới, giữ gốc mỗi phiên bản. Bộ nhớ ~ n·log n nút (khai báo mảng 20·n đến 40·n).
- Phần tử nhỏ thứ k trên đoạn [l, r]: nén giá trị, phiên bản i = cây đếm của tiền tố a[1..i], đi xuống đồng thời trên root[r] và root[l-1].
```cpp
int L[M], R[M], cnt[M], tot;
int upd(int prev, int lo, int hi, int pos) { int cur = ++tot; L[cur] = L[prev]; R[cur] = R[prev]; cnt[cur] = cnt[prev] + 1;
  if (lo < hi) { int mid = (lo + hi) / 2; if (pos <= mid) L[cur] = upd(L[prev], lo, mid, pos); else R[cur] = upd(R[prev], mid + 1, hi, pos); }
  return cur; }
int kth(int u, int v, int lo, int hi, int k) { if (lo == hi) return lo; int mid = (lo + hi) / 2, c = cnt[L[v]] - cnt[L[u]];
  return k <= c ? kth(L[u], L[v], lo, mid, k) : kth(R[u], R[v], mid + 1, hi, k - c); }
```

Implicit treap: mảng hỗ trợ chèn/xoá ở vị trí bất kỳ, đảo đoạn, tổng đoạn trong O(log n) kỳ vọng.
```cpp
mt19937 rng(712367); struct Node { int pri, sz = 1; long long val, sum; bool rev = false; Node *l = nullptr, *r = nullptr; Node(long long v): pri(rng()), val(v), sum(v) {} };
int sz(Node* t) { return t ? t->sz : 0; } long long sm(Node* t) { return t ? t->sum : 0; }
void push(Node* t) { if (t && t->rev) { swap(t->l, t->r); if (t->l) t->l->rev ^= 1; if (t->r) t->r->rev ^= 1; t->rev = false; } }
void pull(Node* t) { t->sz = 1 + sz(t->l) + sz(t->r); t->sum = t->val + sm(t->l) + sm(t->r); }
void split(Node* t, int k, Node*& a, Node*& b) { if (!t) { a = b = nullptr; return; } push(t);
  if (sz(t->l) < k) { split(t->r, k - sz(t->l) - 1, t->r, b); a = t; } else { split(t->l, k, a, t->l); b = t; } pull(t); }
Node* merge(Node* a, Node* b) { push(a); push(b); if (!a || !b) return a ? a : b;
  if (a->pri > b->pri) { a->r = merge(a->r, b); pull(a); return a; } b->l = merge(a, b->l); pull(b); return b; }
```
Đảo đoạn [l, r]: split thành 3 phần, bật cờ rev ở phần giữa, merge lại.

Thêm đường y = kx + b, truy vấn min tại x, mỗi thao tác O(log C), không cần hệ số góc đơn điệu.
```cpp
struct Line { long long k, b; long long f(long long x) const { return k * x + b; } };
vector<Line> t(4 * N, {0, LLONG_MAX / 4});
void add(Line nw, int v, int l, int r) { int m = (l + r) / 2; bool lef = nw.f(l) < t[v].f(l), mid = nw.f(m) < t[v].f(m);
  if (mid) swap(t[v], nw); if (l == r) return; if (lef != mid) add(nw, 2 * v, l, m); else add(nw, 2 * v + 1, m + 1, r); }
long long query(int x, int v, int l, int r) { long long res = t[v].f(x); if (l == r) return res; int m = (l + r) / 2;
  return min(res, x <= m ? query(x, 2 * v, l, m) : query(x, 2 * v + 1, m + 1, r)); }
```
Toạ độ x lớn: nén các x truy vấn trước.

