Mỗi số chèn vào cơ sở tối đa 60 phần tử; trả lời XOR lớn nhất của một tập con, kiểm tra một số có biểu diễn được không, đếm số giá trị XOR khác nhau (= 2^rank).
```cpp
struct XorBasis { long long b[61] = {}; int rank = 0;
  bool insert(long long x) { for (int i = 60; i >= 0; --i) if (x >> i & 1) { if (!b[i]) { b[i] = x; ++rank; return true; } x ^= b[i]; } return false; }
