- Trên đường đi của cây/đoạn: cơ sở "tiền tố" giữ phần tử có chỉ số lớn nhất ở mỗi bit.

```cpp
// Giải A x = b mod p (p nguyên tố). a là ma trận n × (m+1) (cột cuối là b). Trả về hạng; -1 nếu vô nghiệm.
long long pw(long long a, long long e, long long p) { long long r = 1; a %= p; for (; e; e >>= 1, a = a * a % p) if (e & 1) r = r * a % p; return r; }
int gauss(vector<vector<long long>>& a, long long p) { int n = a.size(), m = a[0].size() - 1, row = 0;
  for (int col = 0; col < m && row < n; ++col) { int sel = row; while (sel < n && !a[sel][col]) ++sel; if (sel == n) continue;
    swap(a[sel], a[row]); long long inv = pw(a[row][col], p - 2, p);
    for (auto& v : a[row]) v = v * inv % p;
    for (int i = 0; i < n; ++i) if (i != row && a[i][col]) { long long f = a[i][col]; for (int j = col; j <= m; ++j) a[i][j] = ((a[i][j] - f * a[row][j]) % p + p) % p; }
    ++row; }
  for (int i = row; i < n; ++i) if (a[i][m]) return -1;
  return row; }
```
- Định thức: khử thành tam giác, nhân đường chéo, đổi dấu khi đổi hàng. Số thực: chọn phần tử chốt có trị tuyệt đối lớn nhất.

O(n) đỉnh, mỗi đỉnh là một palindrome khác nhau; đếm số palindrome khác nhau, số lần xuất hiện, palindrome dài nhất kết thúc tại mỗi vị trí.
```cpp
struct Eertree { vector<array<int,26>> nx; vector<int> len, link, cnt; string s; int last = 1;
  Eertree() { nx.assign(2, {}); len = {-1, 0}; link = {0, 0}; cnt = {0, 0}; }
  int find(int v, int i) { while (i - len[v] - 1 < 0 || s[i - len[v] - 1] != s[i]) v = link[v]; return v; }
  void add(char ch) { s += ch; int i = s.size() - 1, c = ch - 'a', v = find(last, i);
    if (!nx[v][c]) { int u = len.size(); len.push_back(len[v] + 2); nx.push_back({}); cnt.push_back(0);
      link.push_back(len[u] == 1 ? 1 : nx[find(link[v], i)][c]); nx[v][c] = u; }
    last = nx[v][c]; ++cnt[last]; }
  // số palindrome khác nhau = len.size() - 2; số lần xuất hiện: cộng cnt theo link từ đỉnh dài về ngắn
};
```

