```cpp
string add(string a, string b) { string r; int c = 0;
  for (int i = a.size() - 1, j = b.size() - 1; i >= 0 || j >= 0 || c; --i, --j) {
    int s = c + (i >= 0 ? a[i] - '0' : 0) + (j >= 0 ? b[j] - '0' : 0); r += char('0' + s % 10); c = s / 10; }
  reverse(r.begin(), r.end()); return r; }
// a >= b
string sub(string a, string b) { string r; int br = 0;
  for (int i = a.size() - 1, j = b.size() - 1; i >= 0; --i, --j) {
    int d = a[i] - '0' - br - (j >= 0 ? b[j] - '0' : 0); br = d < 0; if (d < 0) d += 10; r += char('0' + d); }
  while (r.size() > 1 && r.back() == '0') r.pop_back(); reverse(r.begin(), r.end()); return r; }
string mul(const string& a, const string& b) { vector<long long> v(a.size() + b.size());
  for (int i = a.size() - 1; i >= 0; --i) for (int j = b.size() - 1; j >= 0; --j) v[i + j + 1] += (a[i] - '0') * (b[j] - '0');
  for (int k = v.size() - 1; k > 0; --k) { v[k - 1] += v[k] / 10; v[k] %= 10; }
  string r; for (long long d : v) if (!r.empty() || d) r += char('0' + d); return r.empty() ? "0" : r; }
pair<string, long long> divSmall(const string& a, long long d) { string q; long long rem = 0;
  for (char ch : a) { rem = rem * 10 + (ch - '0'); if (!q.empty() || rem / d) q += char('0' + rem / d); rem %= d; }
  return {q.empty() ? "0" : q, rem}; }
```
- Nhân hai số rất dài (10^5 chữ số): dùng FFT/NTT. Python có sẵn số nguyên lớn: với bài cho phép Python, dùng luôn `int`.

```cpp
const int MOD = 998244353, G = 3;
long long pw(long long a, long long e) { long long r = 1; a %= MOD; for (; e; e >>= 1, a = a * a % MOD) if (e & 1) r = r * a % MOD; return r; }
void ntt(vector<long long>& a, bool inv) { int n = a.size();
  for (int i = 1, j = 0; i < n; ++i) { int bit = n >> 1; for (; j & bit; bit >>= 1) j ^= bit; j ^= bit; if (i < j) swap(a[i], a[j]); }
  for (int len = 2; len <= n; len <<= 1) { long long w = pw(G, (MOD - 1) / len); if (inv) w = pw(w, MOD - 2);
    for (int i = 0; i < n; i += len) { long long wn = 1;
      for (int j = 0; j < len / 2; ++j) { long long u = a[i + j], v = a[i + j + len / 2] * wn % MOD;
        a[i + j] = (u + v) % MOD; a[i + j + len / 2] = (u - v + MOD) % MOD; wn = wn * w % MOD; } } }
  if (inv) { long long ni = pw(n, MOD - 2); for (auto& x : a) x = x * ni % MOD; } }
vector<long long> multiply(vector<long long> a, vector<long long> b) { int need = a.size() + b.size() - 1, n = 1;
  while (n < need) n <<= 1; a.resize(n); b.resize(n); ntt(a, false); ntt(b, false);
  for (int i = 0; i < n; ++i) a[i] = a[i] * b[i] % MOD; ntt(a, true); a.resize(need); return a; }
```
Không có modulo (hệ số nhỏ): dùng FFT số phức, làm tròn `llround`.

```cpp
struct Dinic { struct E { int to; long long cap; }; vector<E> e; vector<vector<int>> g; vector<int> lvl, it;
  Dinic(int n): g(n), lvl(n), it(n) {}
  void add(int u, int v, long long c) { g[u].push_back(e.size()); e.push_back({v, c}); g[v].push_back(e.size()); e.push_back({u, 0}); }
  bool bfs(int s, int t) { fill(lvl.begin(), lvl.end(), -1); queue<int> q; q.push(s); lvl[s] = 0;
    while (!q.empty()) { int u = q.front(); q.pop(); for (int id : g[u]) if (e[id].cap > 0 && lvl[e[id].to] < 0) { lvl[e[id].to] = lvl[u] + 1; q.push(e[id].to); } }
    return lvl[t] >= 0; }
  long long dfs(int u, int t, long long f) { if (u == t) return f;
    for (int& i = it[u]; i < (int)g[u].size(); ++i) { int id = g[u][i]; int v = e[id].to;
      if (e[id].cap > 0 && lvl[v] == lvl[u] + 1) { long long d = dfs(v, t, min(f, e[id].cap));
        if (d > 0) { e[id].cap -= d; e[id ^ 1].cap += d; return d; } } }
    return 0; }
  long long maxflow(int s, int t) { long long flow = 0; while (bfs(s, t)) { fill(it.begin(), it.end(), 0); while (long long f = dfs(s, t, LLONG_MAX)) flow += f; } return flow; } };
```
Sau khi chạy, các đỉnh còn tới được từ s trên đồ thị dư (cap > 0) là phía s của lát cắt nhỏ nhất.

