```cpp
typedef long long ll; struct P { ll x, y; bool operator<(const P& o) const { return x < o.x || (x == o.x && y < o.y); } };
ll cross(P o, P a, P b) { return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x); }
vector<P> hull(vector<P> p) { sort(p.begin(), p.end()); p.erase(unique(p.begin(), p.end(), [](P a, P b) { return a.x == b.x && a.y == b.y; }), p.end());
  if (p.size() < 3) return p; vector<P> h(2 * p.size()); int k = 0;
  for (size_t i = 0; i < p.size(); ++i) { while (k >= 2 && cross(h[k - 2], h[k - 1], p[i]) <= 0) --k; h[k++] = p[i]; }
  for (int i = p.size() - 2, t = k + 1; i >= 0; --i) { while (k >= t && cross(h[k - 2], h[k - 1], p[i]) <= 0) --k; h[k++] = p[i]; }
  h.resize(k - 1); return h; }  // ngược chiều kim đồng hồ, bỏ điểm thẳng hàng
```
Diện tích ×2 = |Σ cross((0,0), h[i], h[i+1])|; giữ điểm thẳng hàng thì đổi `<= 0` thành `< 0`.

```cpp
typedef long long ll; struct P { ll x, y; };
ll cross(P o, P a, P b) { return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x); }
bool onSeg(P a, P b, P p) { return cross(a, b, p) == 0 && min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) && min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y); }
// 1: trong, 0: trên cạnh, -1: ngoài
int inPolygon(const vector<P>& poly, P p) { bool in = false; int n = poly.size();
  for (int i = 0; i < n; ++i) { P a = poly[i], b = poly[(i + 1) % n]; if (onSeg(a, b, p)) return 0;
    if ((a.y > p.y) != (b.y > p.y) && (cross(a, b, p) > 0) == (b.y > a.y)) in = !in; }
  return in ? 1 : -1; }
bool segInter(P a, P b, P c, P d) { ll d1 = cross(a, b, c), d2 = cross(a, b, d), d3 = cross(c, d, a), d4 = cross(c, d, b);
  if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) return true;
  return onSeg(a, b, c) || onSeg(a, b, d) || onSeg(c, d, a) || onSeg(c, d, b); }
