```cpp
vector<int> suffixArray(const string& s0) { string s = s0 + char(0); int n = s.size();
  vector<int> p(n), c(n), pn(n), cn(n), cnt(max(256, n));
  for (char ch : s) cnt[(unsigned char)ch]++; for (int i = 1; i < 256; ++i) cnt[i] += cnt[i - 1];
  for (int i = n - 1; i >= 0; --i) p[--cnt[(unsigned char)s[i]]] = i;
  int cls = 1; c[p[0]] = 0; for (int i = 1; i < n; ++i) { if (s[p[i]] != s[p[i - 1]]) ++cls; c[p[i]] = cls - 1; }
  for (int h = 0; (1 << h) < n; ++h) {
    for (int i = 0; i < n; ++i) pn[i] = ((p[i] - (1 << h)) % n + n) % n;
    fill(cnt.begin(), cnt.begin() + cls, 0); for (int i = 0; i < n; ++i) cnt[c[pn[i]]]++;
    for (int i = 1; i < cls; ++i) cnt[i] += cnt[i - 1];
    for (int i = n - 1; i >= 0; --i) p[--cnt[c[pn[i]]]] = pn[i];
    cn[p[0]] = 0; cls = 1;
    for (int i = 1; i < n; ++i) { pair<int,int> cur = {c[p[i]], c[(p[i] + (1 << h)) % n]}, prev = {c[p[i - 1]], c[(p[i - 1] + (1 << h)) % n]};
      if (cur != prev) ++cls; cn[p[i]] = cls - 1; }
    c.swap(cn); }
  p.erase(p.begin()); return p; }
vector<int> lcpArray(const string& s, const vector<int>& sa) { int n = s.size(), k = 0; vector<int> rk(n), lcp(max(0, n - 1));
  for (int i = 0; i < n; ++i) rk[sa[i]] = i;
  for (int i = 0; i < n; ++i) { if (rk[i] == n - 1) { k = 0; continue; } int j = sa[rk[i] + 1];
    while (i + k < n && j + k < n && s[i + k] == s[j + k]) ++k; lcp[rk[i]] = k; if (k) --k; }
  return lcp; }  // lcp[i] = LCP(sa[i], sa[i+1])
```
Số xâu con khác nhau = n(n+1)/2 − Σ lcp.

