// d1[i]: số palindrome lẻ tâm i (bán kính), d2[i]: số palindrome chẵn tâm giữa i-1 và i
void manacher(const string& s, vector<int>& d1, vector<int>& d2) { int n = s.size(); d1.assign(n, 0); d2.assign(n, 0);
  for (int i = 0, l = 0, r = -1; i < n; ++i) { int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
    while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) ++k; d1[i] = k--; if (i + k > r) { l = i - k; r = i + k; } }
  for (int i = 0, l = 0, r = -1; i < n; ++i) { int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);
    while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) ++k; d2[i] = k--; if (i + k > r) { l = i - k - 1; r = i + k; } } }
```
Palindrome dài nhất = max(2·d1[i] − 1, 2·d2[i]). Tổng số palindrome = Σ d1 + Σ d2.

```cpp
vector<int> zfunc(const string& s) { int n = s.size(); vector<int> z(n);
  for (int i = 1, l = 0, r = 0; i < n; ++i) { if (i < r) z[i] = min(r - i, z[i - l]);
    while (i + z[i] < n && s[z[i]] == s[i + z[i]]) ++z[i]; if (i + z[i] > r) { l = i; r = i + z[i]; } }
  z[0] = n; return z; }
