long long extgcd(long long a, long long b, long long& x, long long& y) { if (!b) { x = 1; y = 0; return a; }
  long long g = extgcd(b, a % b, y, x); y -= a / b * x; return g; }
// x ≡ r1 (mod m1), x ≡ r2 (mod m2) → trả về {r, lcm} hoặc {-1, -1} nếu vô nghiệm
pair<long long, long long> crt(long long r1, long long m1, long long r2, long long m2) { long long p, q; long long g = extgcd(m1, m2, p, q);
  if ((r2 - r1) % g) return {-1, -1}; long long l = m1 / g * m2;
  long long t = (__int128)((r2 - r1) / g) * p % (m2 / g); long long r = ((__int128)m1 * t + r1) % l; if (r < 0) r += l; return {r, l}; }
long long phi(long long n) { long long r = n; for (long long p = 2; p * p <= n; ++p) if (n % p == 0) { while (n % p == 0) n /= p; r -= r / p; }
  if (n > 1) r -= r / n; return r; }
```
Sàng phi cho mọi số ≤ N: `phi[i] = i`; với mỗi nguyên tố p: `phi[j] -= phi[j] / p` cho j bội p.

