int editDistance(const string& a, const string& b) { int n = a.size(), m = b.size(); vector<int> prev(m + 1), cur(m + 1);
  iota(prev.begin(), prev.end(), 0);
  for (int i = 1; i <= n; ++i) { cur[0] = i;
    for (int j = 1; j <= m; ++j) cur[j] = min({prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] != b[j - 1])});
    swap(prev, cur); }
  return prev[m]; }
```
