struct Sparse { vector<vector<int>> t;
  Sparse(const vector<int>& a) { int n = a.size(), K = __lg(max(1, n)) + 1; t.assign(K, a);
    for (int k = 1; k < K; ++k) for (int i = 0; i + (1 << k) <= n; ++i) t[k][i] = min(t[k - 1][i], t[k - 1][i + (1 << (k - 1))]); }
  int query(int l, int r) { int k = __lg(r - l + 1); return min(t[k][l], t[k][r - (1 << k) + 1]); } };  // [l, r]
