```cpp
struct RangeBIT { int n; vector<long long> b1, b2; RangeBIT(int n): n(n), b1(n + 2), b2(n + 2) {}
  void add(vector<long long>& b, int i, long long v) { for (; i <= n; i += i & -i) b[i] += v; }
  long long sum(vector<long long>& b, int i) { long long s = 0; for (; i > 0; i -= i & -i) s += b[i]; return s; }
  void rangeAdd(int l, int r, long long v) { add(b1, l, v); add(b1, r + 1, -v); add(b2, l, v * (l - 1)); add(b2, r + 1, -v * r); }
  long long prefix(int i) { return sum(b1, i) * i - sum(b2, i); }
  long long rangeSum(int l, int r) { return prefix(r) - prefix(l - 1); } };  // chỉ số 1..n
```

Lưu `d[v]` = giá trị(v) − giá trị(cha của v); trả lời "x − y = ?" hoặc phát hiện mâu thuẫn.
```cpp
struct WDSU { vector<int> p; vector<long long> d; WDSU(int n): p(n), d(n) { iota(p.begin(), p.end(), 0); }
  int find(int x) { if (p[x] == x) return x; int r = find(p[x]); d[x] += d[p[x]]; p[x] = r; return r; }
  // ghi nhận val[x] - val[y] = w; trả về false nếu mâu thuẫn
  bool unite(int x, int y, long long w) { int rx = find(x), ry = find(y);
    if (rx == ry) return d[x] - d[y] == w; p[rx] = ry; d[rx] = w + d[y] - d[x]; return true; }
  long long diff(int x, int y) { find(x); find(y); return d[x] - d[y]; } };
```
