const long long INF = LLONG_MAX / 4;
// trả về false nếu có chu trình âm đi tới được từ s
bool bellmanFord(int n, const vector<array<long long, 3>>& edges, int s, vector<long long>& d) {
  d.assign(n, INF); d[s] = 0;
  for (int it = 0; it < n; ++it) { bool changed = false;
    for (auto [u, v, w] : edges) if (d[u] < INF && d[u] + w < d[v]) { d[v] = d[u] + w; changed = true; }
    if (!changed) return true; if (it == n - 1) return false; }
  return true; }
