const long long INF = LLONG_MAX / 4;
void floyd(vector<vector<long long>>& d, vector<vector<int>>& nxt) { int n = d.size(); nxt.assign(n, vector<int>(n, -1));
  for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) if (d[i][j] < INF) nxt[i][j] = j;
  for (int k = 0; k < n; ++k) for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j)
    if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j]) { d[i][j] = d[i][k] + d[k][j]; nxt[i][j] = nxt[i][k]; } }
vector<int> path(int u, int v, const vector<vector<int>>& nxt) { if (nxt[u][v] < 0) return {}; vector<int> p{u}; while (u != v) p.push_back(u = nxt[u][v]); return p; }
