// trả về thứ tự topo; rỗng nếu có chu trình. Dùng priority_queue<int, vector<int>, greater<int>> để có thứ tự nhỏ nhất theo từ điển.
vector<int> topo(int n, const vector<vector<int>>& g) { vector<int> indeg(n), order; for (int u = 0; u < n; ++u) for (int v : g[u]) indeg[v]++;
  queue<int> q; for (int u = 0; u < n; ++u) if (!indeg[u]) q.push(u);
  while (!q.empty()) { int u = q.front(); q.pop(); order.push_back(u); for (int v : g[u]) if (!--indeg[v]) q.push(v); }
  if ((int)order.size() < n) order.clear(); return order; }
