int timer_ = 0; vector<vector<pair<int,int>>> g; vector<int> tin, low; vector<pair<int,int>> bridges; vector<char> isCut;
void dfs(int u, int pe) { tin[u] = low[u] = ++timer_; int kids = 0;
  for (auto [v, id] : g[u]) { if (id == pe) continue;
    if (tin[v]) low[u] = min(low[u], tin[v]);
    else { dfs(v, id); low[u] = min(low[u], low[v]); ++kids;
      if (low[v] > tin[u]) bridges.push_back({u, v});
      if (pe != -1 && low[v] >= tin[u]) isCut[u] = 1; } }
  if (pe == -1 && kids > 1) isCut[u] = 1; }
// g[u] chứa (v, id cạnh); tin.assign(n,0); low.assign(n,0); isCut.assign(n,0); for u: if (!tin[u]) dfs(u, -1);
