  int maxXor(int x) { int u = 0, r = 0; for (int b = 30; b >= 0; --b) { int c = x >> b & 1; if (nx[u][!c]) { r |= 1 << b; u = nx[u][!c]; } else u = nx[u][c]; } return r; } };
