struct Aho { vector<array<int,26>> go{{}}; vector<int> link{0}, out{0};
  int add(const string& s) { int u = 0; for (char ch : s) { int c = ch - 'a'; if (!go[u][c]) { go[u][c] = go.size(); go.push_back({}); link.push_back(0); out.push_back(0); } u = go[u][c]; } out[u]++; return u; }
