typedef vector<vector<long long>> Mat; const long long MOD = 1e9 + 7;
Mat mul(const Mat& A, const Mat& B) { int n = A.size(), m = B[0].size(), k = B.size(); Mat C(n, vector<long long>(m));
  for (int i = 0; i < n; ++i) for (int t = 0; t < k; ++t) if (A[i][t]) for (int j = 0; j < m; ++j) C[i][j] = (C[i][j] + A[i][t] * B[t][j]) % MOD; return C; }
Mat power(Mat A, long long e) { int n = A.size(); Mat R(n, vector<long long>(n)); for (int i = 0; i < n; ++i) R[i][i] = 1;
  for (; e; e >>= 1, A = mul(A, A)) if (e & 1) R = mul(R, A); return R; }
// Fibonacci: [[1,1],[1,0]]^n → F(n) = power(...)[0][1]
