const long long MOD = 1e9 + 7; vector<long long> fact, inv;
long long pw(long long a, long long e) { long long r = 1; a %= MOD; for (; e; e >>= 1, a = a * a % MOD) if (e & 1) r = r * a % MOD; return r; }
void initComb(int N) { fact.assign(N + 1, 1); inv.assign(N + 1, 1); for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
  inv[N] = pw(fact[N], MOD - 2); for (int i = N; i > 0; --i) inv[i - 1] = inv[i] * i % MOD; }
long long C(int n, int k) { return k < 0 || k > n ? 0 : fact[n] * inv[k] % MOD * inv[n - k] % MOD; }
