// chu trình ngắn nhất đi qua mọi đỉnh, bắt đầu và kết thúc ở 0; n ≤ 20
long long tsp(const vector<vector<long long>>& w) { int n = w.size(); const long long INF = LLONG_MAX / 4;
  vector<vector<long long>> dp(1 << n, vector<long long>(n, INF)); dp[1][0] = 0;
  for (int mask = 1; mask < (1 << n); ++mask) for (int u = 0; u < n; ++u) if (dp[mask][u] < INF)
    for (int v = 0; v < n; ++v) if (!(mask >> v & 1)) dp[mask | 1 << v][v] = min(dp[mask | 1 << v][v], dp[mask][u] + w[u][v]);
  long long best = INF; for (int u = 1; u < n; ++u) best = min(best, dp[(1 << n) - 1][u] + w[u][0]); return n == 1 ? 0 : best; }
