struct StrHash { static const long long M1 = 1e9 + 7, M2 = 998244353; long long B; vector<long long> h1, h2, p1, p2;
  StrHash(const string& s, long long base = 131) : B(base) { int n = s.size(); h1.assign(n + 1, 0); h2 = h1; p1.assign(n + 1, 1); p2 = p1;
    for (int i = 0; i < n; ++i) { h1[i + 1] = (h1[i] * B + s[i]) % M1; h2[i + 1] = (h2[i] * B + s[i]) % M2; p1[i + 1] = p1[i] * B % M1; p2[i + 1] = p2[i] * B % M2; } }
  pair<long long,long long> get(int l, int r) {  // [l, r)
    return {((h1[r] - h1[l] * p1[r - l]) % M1 + M1) % M1, ((h2[r] - h2[l] * p2[r - l]) % M2 + M2) % M2}; } };
