typedef long long ll;
ll area2(const vector<pair<ll,ll>>& p) { ll s = 0; int n = p.size(); for (int i = 0; i < n; ++i) { auto [x1, y1] = p[i]; auto [x2, y2] = p[(i + 1) % n]; s += x1 * y2 - x2 * y1; } return llabs(s); }  // = 2 × diện tích
ll boundaryPoints(const vector<pair<ll,ll>>& p) { ll b = 0; int n = p.size(); for (int i = 0; i < n; ++i) b += std::gcd(llabs(p[i].first - p[(i + 1) % n].first), llabs(p[i].second - p[(i + 1) % n].second)); return b; }
// Pick: S = I + B/2 − 1  ⇒  số điểm nguyên bên trong I = (area2 − B + 2) / 2
