// Mỗi lượt bốc một số sỏi thuộc tập moves; nhiều đống độc lập → XOR các Grundy
vector<int> grundy(int N, const vector<int>& moves) { vector<int> g(N + 1);
  for (int x = 1; x <= N; ++x) { vector<char> seen(moves.size() + 2, 0);
    for (int m : moves) if (m <= x && g[x - m] < (int)seen.size()) seen[g[x - m]] = 1;
    while (seen[g[x]]) ++g[x]; }
  return g; }
// người đi trước thắng ⇔ XOR của g[a_i] ≠ 0
